#!/bin/bash
# UI checks in headless Chrome (minimap close/Esc/aria, title shows saved area, favicon, ice-A guide arrow). Screenshots -> shots/v2_ui_*.png
cd "$(dirname "$0")"; fail=0
chk(){ echo "$1" | grep -q '"ok": true' && echo "ok $2" || { echo "FAIL $2: $1"; fail=1; }; }
r=$(EVAL="(async()=>{const m=document.getElementById('mini'),x=document.getElementById('miniX');const lbl=m.getAttribute('aria-label');m.dispatchEvent(new PointerEvent('pointerup',{bubbles:true}));const big=m.classList.contains('big'),xs=getComputedStyle(x).display!=='none';const a=m.getBoundingClientRect(),b=x.getBoundingClientRect();const overlap=!(a.right<=b.left||a.left>=b.right||a.bottom<=b.top||a.top>=b.bottom);dispatchEvent(new KeyboardEvent('keydown',{key:'Escape',bubbles:true}));const closed=!m.classList.contains('big')&&getComputedStyle(x).display==='none';m.dispatchEvent(new PointerEvent('pointerup',{bubbles:true}));const big2=m.classList.contains('big');x.dispatchEvent(new PointerEvent('pointerup',{bubbles:true}));const closed2=!m.classList.contains('big');m.dispatchEvent(new PointerEvent('pointerup',{bubbles:true}));return {ok:!!lbl&&big&&xs&&!overlap&&closed&&big2&&closed2,lbl,big,xs,overlap,closed,closed2}})()" ./cdp.py 390x844m "world.html?new&noassist&at=ice&wait=1" shots/v2_ui_minimap_390.png 1 | grep EVAL)
chk "$r" "minimap: aria-label, ✕ visible, map not covering ✕, Esc and ✕ close"
# title with a saved desert game: test-seed.html writes the save then opens world.html?title
SEED=$(node -e "global.window=global;const E=require('./world-engine.js'),W=E.parseWorld(require('./world/world-def.js'));const s=E.initState(W);Object.assign(s,{m:'desert',x:33,y:5,zone:null,visited:['grass','ice','desert'],inv:'cfkm'});process.stdout.write(encodeURIComponent(JSON.stringify({v:4,s,tutorialDone:true})))")
for sz in 390x844m 1440x900; do r=$(EVAL="({ok:document.getElementById('title').classList.contains('on')&&document.getElementById('mapname').textContent.indexOf('沙漠')>=0&&document.getElementById('hint').textContent.length>2&&!document.getElementById('help').classList.contains('on'),map:document.getElementById('mapname').textContent,hint:document.getElementById('hint').textContent})" ./cdp.py $sz "test-seed.html#$SEED" shots/v2_ui_title_${sz%%x*}.png 2 | grep EVAL); chk "$r" "title shows saved map + hint ($sz)"; done
r=$(EVAL="({ok:!!document.querySelector('link[rel=icon][href=\"favicon.ico\"]')})" ./cdp.py 390x844m "world.html?new&noassist&wait=1" - 1 | grep EVAL); chk "$r" "favicon link"
[ -s dist/favicon.ico ] && [ -s dist/favicon-32.png ] && echo "ok dist favicons" || { echo "FAIL dist favicons"; fail=1; }
r=$(EVAL="({ok:typeof guide!=='undefined'&&__world.state().m==='ice'&&guide.until>performance.now()})" EVAL_WAIT=0.3 ./cdp.py 390x844m "world.html?new&noassist&at=ice&wait=1" shots/v2_ui_iceA_arrow_390.png 1 | grep EVAL); chk "$r" "ice A guide arrow active on arrival"
EVAL_WAIT=0.3 EVAL="1" ./cdp.py 1440x900 "world.html?new&noassist&at=ice&wait=1" shots/v2_ui_iceA_arrow_1440.png 1 >/dev/null
# level mode (關卡模式) was removed 2026-10-23: menu/help must not mention or link it, dist must not ship it (levels.html = redirect stub only)
r=$(EVAL="({ok:document.querySelectorAll('#menu button,#menu a').length===2&&!document.querySelector('a[href*=levels],a[href=\\\"index.html\\\"]')&&document.body.innerHTML.indexOf('關卡模式')<0&&typeof LEVELS==='undefined'&&!__errs.length,n:document.querySelectorAll('#menu button,#menu a').length,errs:__errs})" ./cdp.py 390x844m "world.html?new&noassist&wait=1" - 1 | grep EVAL); chk "$r" "menu has no level mode"
[ ! -e dist/game.js ] && [ ! -e dist/levels.js ] && grep -q "location.replace" dist/levels.html && ! grep -q "關卡模式\|levels\.html\|src=\"levels\.js\|src=\"game\.js\|\"game\.js\":" dist/index.html && echo "ok dist has no level mode" || { echo "FAIL dist has no level mode"; fail=1; }
exit $fail
